import { Box } from "@/shared/ui/layout/Box";
import { TracePlayer } from "@/features/algorithms/viz/TracePlayer";

interface VizExample { factory: () => Generator<unknown>; renderers?: Record<string, unknown> }

export function VizPreview({
  viz = { factory: function* () { yield { structure: "array", data: [3, 1, 4, 1, 5] }; } },
  onExpand = () => {},
}: { viz?: VizExample; onExpand?: () => void }) {
  return (
    <Box
      className="algo-viz-preview"
      role="button"
      tabIndex={0}
      aria-label="Expand visualization — take a closer look and try your own input"
      title="Expand — take a closer look and try your own input"
      onClick={onExpand}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onExpand();
        }
      }}
    >
      <TracePlayer factory={viz.factory as () => Generator<any>} renderers={viz.renderers as any} fps={3} autoPlay loop controls={false} />
      <Box as="span" className="algo-viz-expand-cue" aria-hidden>
        ⤢ Expand
      </Box>
    </Box>
  );
}
